def add_users(conn, rows):
    if not rows:
        return
    try:
        conn.execute("BEGIN")
        for user_id, name in rows:
            conn.execute("INSERT INTO users(id, name) VALUES (?, ?)", (user_id, name))
        conn.commit()
    except Exception:
        conn.rollback()
        raise

